const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const root_module = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{
        .name = "kvhttp",
        .root_module = root_module,
    });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    const run_step = b.step("run", "Run the server");
    run_step.dependOn(&run_cmd.step);

    const tests = b.addTest(.{ .root_module = root_module });
    const test_step = b.step("test", "Run unit tests");
    test_step.dependOn(&b.addRunArtifact(tests).step);
}

//! The kvhttp HTTP server: accepts connections, routes requests and applies
//! them to the store. Each connection carries one request and is served by
//! its own concurrent task.

const std = @import("std");
const Io = std.Io;
const net = Io.net;
const Allocator = std.mem.Allocator;

const http = @import("http.zig");
const Store = @import("Store.zig");

const log = std.log.scoped(.server);

const Server = @This();

io: Io,
gpa: Allocator,
store: *Store,

pub const max_value_len = 1024 * 1024;
pub const max_key_len = 64;

/// Request bodies nobody asked for (or that were rejected as too large) are
/// read and dropped up to this size so that closing the socket does not
/// reset the connection before the client has read the response.
const max_discard_len = 64 * 1024 * 1024;

/// Accepts connections forever, serving each one concurrently.
pub fn run(server: *Server, listener: *net.Server) Io.Cancelable!void {
    const io = server.io;
    var group: Io.Group = .init;
    defer group.cancel(io);

    while (true) {
        const stream = listener.accept(io) catch |err| switch (err) {
            error.Canceled => return error.Canceled,
            error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded, error.SystemResources => {
                // Back off instead of spinning until connections are released.
                log.warn("accept failed: {t}", .{err});
                try io.sleep(.fromMilliseconds(10), .awake);
                continue;
            },
            else => {
                log.warn("accept failed: {t}", .{err});
                continue;
            },
        };
        group.concurrent(io, serveConnection, .{ server, stream }) catch {
            // No more threads available: serve this connection inline.
            serveConnection(server, stream);
        };
    }
}

fn serveConnection(server: *Server, stream: net.Stream) void {
    const io = server.io;
    defer stream.close(io);

    var recv_buffer: [http.max_head_len]u8 = undefined;
    var send_buffer: [8 * 1024]u8 = undefined;
    var stream_reader = stream.reader(io, &recv_buffer);
    var stream_writer = stream.writer(io, &send_buffer);

    server.serveRequest(&stream_reader.interface, &stream_writer.interface) catch |err| switch (err) {
        error.ReadFailed => log.debug("read failed: {t}", .{stream_reader.err.?}),
        error.WriteFailed => log.debug("write failed: {t}", .{stream_writer.err.?}),
    };
}

const ServeError = error{ ReadFailed, WriteFailed };

fn serveRequest(server: *Server, in: *Io.Reader, out: *Io.Writer) ServeError!void {
    const head = http.readHead(in) catch |err| return switch (err) {
        // The client went away without sending a request.
        error.EndOfStream => {},
        error.ReadFailed => error.ReadFailed,
        error.HeadTooLarge => http.writeResponse(out, .plain(.request_header_fields_too_large)),
        error.BadRequest => http.writeResponse(out, .plain(.bad_request)),
        error.ExpectationFailed => http.writeResponse(out, .plain(.expectation_failed)),
    };

    // Holds response bodies until they have been written.
    var arena: std.heap.ArenaAllocator = .init(server.gpa);
    defer arena.deinit();

    var response = switch (resolve(head.method, head.target)) {
        .put => |key| try server.put(in, out, head, key),
        else => |route| blk: {
            discardBody(in, head) catch |err| switch (err) {
                error.ReadFailed => return error.ReadFailed,
                else => {},
            };
            break :blk server.apply(arena.allocator(), route);
        },
    };
    response.elide_body = std.mem.eql(u8, head.method, "HEAD");
    try http.writeResponse(out, response);
}

/// Handles `PUT /kv/<key>`: reads the value and stores it.
fn put(server: *Server, in: *Io.Reader, out: *Io.Writer, head: http.Head, key_ref: []const u8) ServeError!http.Response {
    // `key_ref` points into the read buffer, which reading the body reuses.
    var key_buffer: [max_key_len]u8 = undefined;
    const key = key_buffer[0..key_ref.len];
    @memcpy(key, key_ref);

    const declared_too_large = (head.content_length orelse 0) > max_value_len;
    if (head.expect_continue and !declared_too_large) try http.writeContinue(out);

    const value = http.readBody(in, server.gpa, head, max_value_len) catch |err| return switch (err) {
        error.ReadFailed => error.ReadFailed,
        error.EndOfStream => .plain(.bad_request),
        error.BadRequest => .plain(.bad_request),
        error.OutOfMemory => .plain(.internal_server_error),
        error.TooLarge => blk: {
            if (declared_too_large) discardBody(in, head) catch |e| switch (e) {
                error.ReadFailed => return error.ReadFailed,
                else => {},
            };
            break :blk .plain(.payload_too_large);
        },
    };

    const created = server.store.put(server.io, key, value) catch |err| {
        server.gpa.free(value);
        log.err("storing value failed: {t}", .{err});
        return .plain(.internal_server_error);
    };
    return .{ .status = if (created) .created else .ok };
}

/// Executes every route except `put`, which needs the request body.
/// Response bodies are allocated with `arena`.
fn apply(server: *Server, arena: Allocator, route: Route) http.Response {
    return server.applyFallible(arena, route) catch |err| {
        log.err("request failed: {t}", .{err});
        return .plain(.internal_server_error);
    };
}

fn applyFallible(server: *Server, arena: Allocator, route: Route) (Allocator.Error || Io.Cancelable)!http.Response {
    const io = server.io;
    return switch (route) {
        .health => .{ .status = .ok, .body = "ok" },
        .list => .{
            .status = .ok,
            .body = try server.store.keysJson(io, arena),
            .content_type = "application/json",
        },
        .get => |key| if (try server.store.get(io, arena, key)) |value| .{
            .status = .ok,
            .body = value,
            .content_type = "application/octet-stream",
        } else .plain(.not_found),
        .delete => |key| if (try server.store.remove(io, key)) .{ .status = .no_content } else .plain(.not_found),
        .reject => |response| response,
        .put => unreachable,
    };
}

/// Drops the request body unless the client is still waiting for
/// `100 Continue` before sending it.
fn discardBody(in: *Io.Reader, head: http.Head) http.BodyError!void {
    if (head.expect_continue or !head.hasBody()) return;
    try http.discardBody(in, head, max_discard_len);
}

pub const Route = union(enum) {
    health,
    list,
    get: []const u8,
    put: []const u8,
    delete: []const u8,
    /// The request is answered with this response without touching the store.
    reject: http.Response,
};

const kv_prefix = "/kv/";

/// Maps a request method and target to a route.
pub fn resolve(method: []const u8, target: []const u8) Route {
    if (std.mem.eql(u8, target, "/health")) {
        if (!std.mem.eql(u8, method, "GET")) return methodNotAllowed("GET");
        return .health;
    }
    if (std.mem.eql(u8, target, "/kv")) {
        if (!std.mem.eql(u8, method, "GET")) return methodNotAllowed("GET");
        return .list;
    }
    if (std.mem.startsWith(u8, target, kv_prefix)) {
        const key = target[kv_prefix.len..];
        if (!isValidKey(key)) return .{ .reject = .{ .status = .bad_request, .body = "invalid key" } };
        const Method = enum { GET, PUT, DELETE };
        return switch (std.meta.stringToEnum(Method, method) orelse return methodNotAllowed("GET, PUT, DELETE")) {
            .GET => .{ .get = key },
            .PUT => .{ .put = key },
            .DELETE => .{ .delete = key },
        };
    }
    return .{ .reject = .plain(.not_found) };
}

fn methodNotAllowed(allow: []const u8) Route {
    var response: http.Response = .plain(.method_not_allowed);
    response.allow = allow;
    return .{ .reject = response };
}

/// Reports whether `key` matches `[A-Za-z0-9_-]{1,64}`.
pub fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > max_key_len) return false;
    for (key) |c| switch (c) {
        'A'...'Z', 'a'...'z', '0'...'9', '_', '-' => {},
        else => return false,
    };
    return true;
}

const testing = std.testing;

test isValidKey {
    try testing.expect(isValidKey("a"));
    try testing.expect(isValidKey("A-z_09"));
    try testing.expect(isValidKey("k" ** 64));
    try testing.expect(!isValidKey(""));
    try testing.expect(!isValidKey("k" ** 65));
    try testing.expect(!isValidKey("bad.key"));
    try testing.expect(!isValidKey("a/b"));
    try testing.expect(!isValidKey("%41"));
}

test resolve {
    try testing.expectEqual(Route.health, resolve("GET", "/health"));
    try testing.expectEqual(Route.list, resolve("GET", "/kv"));
    try testing.expectEqualStrings("abc", resolve("GET", "/kv/abc").get);
    try testing.expectEqualStrings("abc", resolve("PUT", "/kv/abc").put);
    try testing.expectEqualStrings("abc", resolve("DELETE", "/kv/abc").delete);

    try testing.expectEqual(.method_not_allowed, resolve("POST", "/health").reject.status);
    try testing.expectEqual(.method_not_allowed, resolve("HEAD", "/kv").reject.status);
    try testing.expectEqual(.method_not_allowed, resolve("PATCH", "/kv/a").reject.status);
    try testing.expectEqual(.bad_request, resolve("PATCH", "/kv/a.b").reject.status);
    try testing.expectEqual(.bad_request, resolve("GET", "/kv/").reject.status);
    try testing.expectEqual(.bad_request, resolve("GET", "/kv/a/b").reject.status);
    try testing.expectEqual(.not_found, resolve("GET", "/nope").reject.status);
    try testing.expectEqual(.not_found, resolve("GET", "/health/").reject.status);
    try testing.expectEqual(.not_found, resolve("GET", "/kvx").reject.status);
}

//! Thread-safe in-memory key-value store holding raw byte values.
//!
//! Keys and values are owned by the store and allocated with `gpa`.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

const Store = @This();

gpa: Allocator,
mutex: Io.Mutex = .init,
map: std.StringHashMapUnmanaged([]u8) = .empty,

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(s: *Store) void {
    var it = s.map.iterator();
    while (it.next()) |entry| {
        s.gpa.free(entry.key_ptr.*);
        s.gpa.free(entry.value_ptr.*);
    }
    s.map.deinit(s.gpa);
    s.* = undefined;
}

/// Stores `value` under `key`, taking ownership of `value`, which must have
/// been allocated with the store's allocator. Returns true if the key was
/// newly created, false if an existing value was replaced.
pub fn put(s: *Store, io: Io, key: []const u8, value: []u8) (Allocator.Error || Io.Cancelable)!bool {
    // Duplicate the key before locking so the critical section stays short.
    // It is freed again if the key turns out to exist already.
    const owned_key = try s.gpa.dupe(u8, key);
    errdefer s.gpa.free(owned_key);

    const old_value: ?[]u8 = blk: {
        try s.mutex.lock(io);
        defer s.mutex.unlock(io);
        const gop = try s.map.getOrPut(s.gpa, owned_key);
        if (gop.found_existing) {
            const old = gop.value_ptr.*;
            gop.value_ptr.* = value;
            break :blk old;
        }
        gop.value_ptr.* = value;
        break :blk null;
    };

    if (old_value) |old| {
        s.gpa.free(owned_key);
        s.gpa.free(old);
        return false;
    }
    return true;
}

/// Returns a copy of the value stored under `key`, allocated with `allocator`,
/// or null if the key is absent. The caller owns the returned memory.
pub fn get(s: *Store, io: Io, allocator: Allocator, key: []const u8) (Allocator.Error || Io.Cancelable)!?[]u8 {
    try s.mutex.lock(io);
    defer s.mutex.unlock(io);
    const value = s.map.get(key) orelse return null;
    return try allocator.dupe(u8, value);
}

/// Removes `key`. Returns true if it was present.
pub fn remove(s: *Store, io: Io, key: []const u8) Io.Cancelable!bool {
    const removed = blk: {
        try s.mutex.lock(io);
        defer s.mutex.unlock(io);
        break :blk s.map.fetchRemove(key) orelse return false;
    };
    s.gpa.free(removed.key);
    s.gpa.free(removed.value);
    return true;
}

/// Returns every key, sorted ascending by byte order, encoded as a JSON array
/// of strings. Keys are restricted to `[A-Za-z0-9_-]`, so no escaping is
/// needed. The caller owns the returned memory.
pub fn keysJson(s: *Store, io: Io, allocator: Allocator) (Allocator.Error || Io.Cancelable)![]u8 {
    var keys: std.ArrayList([]const u8) = .empty;
    defer keys.deinit(allocator);
    var json: std.ArrayList(u8) = .empty;
    errdefer json.deinit(allocator);

    try s.mutex.lock(io);
    defer s.mutex.unlock(io);

    try keys.ensureTotalCapacityPrecise(allocator, s.map.count());
    var json_len: usize = 2; // "[" and "]"
    var it = s.map.keyIterator();
    while (it.next()) |key| {
        keys.appendAssumeCapacity(key.*);
        json_len += key.len + 3; // quotes and separator
    }
    std.mem.sortUnstable([]const u8, keys.items, {}, lessThan);

    try json.ensureTotalCapacityPrecise(allocator, json_len);
    json.appendAssumeCapacity('[');
    for (keys.items, 0..) |key, i| {
        if (i != 0) json.appendAssumeCapacity(',');
        json.appendAssumeCapacity('"');
        json.appendSliceAssumeCapacity(key);
        json.appendAssumeCapacity('"');
    }
    json.appendAssumeCapacity(']');
    return json.toOwnedSlice(allocator);
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

const testing = std.testing;

test "put, get, remove" {
    const io = testing.io;
    var store: Store = .init(testing.allocator);
    defer store.deinit();

    try testing.expect(try store.put(io, "a", try testing.allocator.dupe(u8, "hello")));
    try testing.expect(!try store.put(io, "a", try testing.allocator.dupe(u8, "world")));

    const value = (try store.get(io, testing.allocator, "a")).?;
    defer testing.allocator.free(value);
    try testing.expectEqualStrings("world", value);

    try testing.expect(try store.remove(io, "a"));
    try testing.expect(!try store.remove(io, "a"));
    try testing.expectEqual(null, try store.get(io, testing.allocator, "a"));
}

test "keys are listed sorted" {
    const io = testing.io;
    var store: Store = .init(testing.allocator);
    defer store.deinit();

    for ([_][]const u8{ "b", "a", "_", "C", "-" }) |key| {
        _ = try store.put(io, key, try testing.allocator.dupe(u8, "v"));
    }

    const json = try store.keysJson(io, testing.allocator);
    defer testing.allocator.free(json);
    try testing.expectEqualStrings("[\"-\",\"C\",\"_\",\"a\",\"b\"]", json);
}

//! Minimal HTTP/1.1 message handling: request heads, request bodies
//! (`Content-Length` or chunked) and responses.
//!
//! The server answers exactly one request per connection, so responses always
//! carry `Connection: close`.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const Status = std.http.Status;

/// Upper bound for the request line plus all header fields. Also the size of
/// the connection read buffer, since the whole head is parsed in place.
pub const max_head_len = 16 * 1024;

pub const Version = enum { @"HTTP/1.0", @"HTTP/1.1" };

pub const Head = struct {
    method: []const u8,
    target: []const u8,
    version: Version,
    content_length: ?u64 = null,
    chunked: bool = false,
    expect_continue: bool = false,

    pub fn hasBody(head: Head) bool {
        return head.chunked or (head.content_length orelse 0) > 0;
    }
};

pub const HeadError = error{
    /// The client closed the connection before sending a complete head.
    EndOfStream,
    ReadFailed,
    /// The head exceeds `max_head_len`.
    HeadTooLarge,
    /// The head is not a well-formed HTTP/1.x request.
    BadRequest,
    /// The request carries an `Expect` value other than `100-continue`.
    ExpectationFailed,
};

/// Reads a request head from `in` and parses it. The returned strings point
/// into the buffer of `in` and are invalidated by the next read from `in`.
///
/// Asserts the buffer of `in` holds at least `max_head_len` bytes.
pub fn readHead(in: *Io.Reader) HeadError!Head {
    std.debug.assert(in.buffer.len >= max_head_len);
    var parser: std.http.HeadParser = .{};
    var scanned: usize = 0;
    while (true) {
        const buffered = in.buffered();
        scanned += parser.feed(buffered[scanned..]);
        if (parser.state == .finished) break;
        if (buffered.len >= max_head_len) return error.HeadTooLarge;
        in.fillMore() catch |err| switch (err) {
            error.EndOfStream => return error.EndOfStream,
            error.ReadFailed => return error.ReadFailed,
        };
    }
    if (scanned > max_head_len) return error.HeadTooLarge;
    return parseHead(in.take(scanned) catch unreachable);
}

/// Parses a complete request head, including the terminating empty line.
pub fn parseHead(bytes: []const u8) HeadError!Head {
    var lines = std.mem.splitScalar(u8, bytes, '\n');

    const request_line = trimCr(lines.first());
    var parts = std.mem.splitScalar(u8, request_line, ' ');
    const method = parts.next().?;
    const target = parts.next() orelse return error.BadRequest;
    const version_text = parts.next() orelse return error.BadRequest;
    if (parts.next() != null) return error.BadRequest;
    if (!isToken(method) or target.len == 0) return error.BadRequest;
    const version = std.meta.stringToEnum(Version, version_text) orelse return error.BadRequest;

    var head: Head = .{ .method = method, .target = target, .version = version };
    var transfer_encoding = false;

    while (lines.next()) |raw_line| {
        const line = trimCr(raw_line);
        if (line.len == 0) break;
        const colon = std.mem.findScalar(u8, line, ':') orelse return error.BadRequest;
        const name = line[0..colon];
        if (!isToken(name)) return error.BadRequest;
        const value = std.mem.trim(u8, line[colon + 1 ..], " \t");

        if (std.ascii.eqlIgnoreCase(name, "content-length")) {
            const length = parseContentLength(value) orelse return error.BadRequest;
            if (head.content_length) |previous| {
                if (previous != length) return error.BadRequest;
            }
            head.content_length = length;
        } else if (std.ascii.eqlIgnoreCase(name, "transfer-encoding")) {
            transfer_encoding = true;
            // Only "chunked" as the final coding can be framed; anything else
            // leaves the body length undeterminable.
            var codings = std.mem.splitBackwardsScalar(u8, value, ',');
            const last = std.mem.trim(u8, codings.first(), " \t");
            head.chunked = std.ascii.eqlIgnoreCase(last, "chunked");
            if (!head.chunked) return error.BadRequest;
        } else if (std.ascii.eqlIgnoreCase(name, "expect")) {
            if (!std.ascii.eqlIgnoreCase(value, "100-continue")) return error.ExpectationFailed;
            head.expect_continue = true;
        }
    }

    // A message with both framings is a request smuggling vector.
    if (transfer_encoding and head.content_length != null) return error.BadRequest;
    return head;
}

fn trimCr(line: []const u8) []const u8 {
    return if (std.mem.endsWith(u8, line, "\r")) line[0 .. line.len - 1] else line;
}

fn isToken(s: []const u8) bool {
    if (s.len == 0) return false;
    for (s) |c| switch (c) {
        'A'...'Z', 'a'...'z', '0'...'9' => {},
        '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~' => {},
        else => return false,
    };
    return true;
}

fn parseContentLength(value: []const u8) ?u64 {
    if (value.len == 0) return null;
    for (value) |c| if (!std.ascii.isDigit(c)) return null;
    return std.fmt.parseInt(u64, value, 10) catch null;
}

pub const BodyError = error{
    EndOfStream,
    ReadFailed,
    OutOfMemory,
    /// The body exceeds the caller's limit.
    TooLarge,
    /// The chunked encoding is malformed.
    BadRequest,
};

/// Reads the whole request body described by `head` into memory allocated
/// with `gpa`. The caller owns the returned slice.
///
/// When `head` declares a `Content-Length` above `limit`, returns
/// `error.TooLarge` without consuming any of the body.
pub fn readBody(in: *Io.Reader, gpa: Allocator, head: Head, limit: usize) BodyError![]u8 {
    if (head.chunked) {
        var body: std.ArrayList(u8) = .empty;
        errdefer body.deinit(gpa);
        try readChunked(in, .{ .gpa = gpa, .list = &body }, limit);
        return body.toOwnedSlice(gpa);
    }
    const length = head.content_length orelse 0;
    if (length > limit) return error.TooLarge;
    const body = try gpa.alloc(u8, @intCast(length));
    errdefer gpa.free(body);
    try in.readSliceAll(body);
    return body;
}

/// Consumes and drops the request body described by `head`, provided it is
/// no larger than `limit` bytes.
pub fn discardBody(in: *Io.Reader, head: Head, limit: usize) BodyError!void {
    if (head.chunked) return readChunked(in, null, limit);
    const length = head.content_length orelse 0;
    if (length > limit) return error.TooLarge;
    try in.discardAll64(length);
}

const Sink = struct {
    gpa: Allocator,
    list: *std.ArrayList(u8),
};

fn readChunked(in: *Io.Reader, sink: ?Sink, limit: usize) BodyError!void {
    var total: u64 = 0;
    while (true) {
        const size_line = try takeLine(in);
        const size_text = std.mem.trim(u8, size_line[0 .. std.mem.findScalar(u8, size_line, ';') orelse size_line.len], " \t");
        if (size_text.len == 0) return error.BadRequest;
        const size = std.fmt.parseInt(u64, size_text, 16) catch return error.BadRequest;
        if (size == 0) break;

        total = std.math.add(u64, total, size) catch return error.TooLarge;
        if (total > limit) return error.TooLarge;
        if (sink) |s| {
            const n: usize = @intCast(size);
            try s.list.ensureUnusedCapacity(s.gpa, n);
            try in.readSliceAll(s.list.unusedCapacitySlice()[0..n]);
            s.list.items.len += n;
        } else {
            try in.discardAll64(size);
        }
        if ((try takeLine(in)).len != 0) return error.BadRequest;
    }
    // Trailer fields are ignored; they end with an empty line.
    while ((try takeLine(in)).len != 0) {}
}

/// Takes one line, without its terminating LF or CRLF.
fn takeLine(in: *Io.Reader) BodyError![]u8 {
    const line = in.takeDelimiterInclusive('\n') catch |err| switch (err) {
        error.StreamTooLong => return error.BadRequest,
        error.EndOfStream => return error.EndOfStream,
        error.ReadFailed => return error.ReadFailed,
    };
    const without_lf = line[0 .. line.len - 1];
    return if (std.mem.endsWith(u8, without_lf, "\r")) without_lf[0 .. without_lf.len - 1] else without_lf;
}

pub const Response = struct {
    status: Status,
    body: []const u8 = "",
    content_type: []const u8 = "text/plain; charset=utf-8",
    /// Value of the `Allow` header, sent with 405 responses.
    allow: ?[]const u8 = null,
    /// Omit the body (but keep its `Content-Length`), as for `HEAD` requests.
    elide_body: bool = false,

    /// A plain-text response whose body is the status' reason phrase.
    pub fn plain(status: Status) Response {
        return .{ .status = status, .body = status.phrase() orelse "" };
    }
};

/// Writes a complete response and flushes `out`.
pub fn writeResponse(out: *Io.Writer, response: Response) Io.Writer.Error!void {
    const status = response.status;
    try out.print("HTTP/1.1 {d} {s}\r\n", .{ @intFromEnum(status), status.phrase() orelse "" });
    if (response.allow) |allow| try out.print("Allow: {s}\r\n", .{allow});
    try out.print("Content-Length: {d}\r\n", .{response.body.len});
    if (response.body.len > 0) try out.print("Content-Type: {s}\r\n", .{response.content_type});
    try out.writeAll("Connection: close\r\n\r\n");
    if (!response.elide_body) try out.writeAll(response.body);
    try out.flush();
}

/// Tells a client that sent `Expect: 100-continue` to transmit the body.
pub fn writeContinue(out: *Io.Writer) Io.Writer.Error!void {
    try out.writeAll("HTTP/1.1 100 Continue\r\n\r\n");
    try out.flush();
}

const testing = std.testing;

test parseHead {
    const head = try parseHead("PUT /kv/a HTTP/1.1\r\nHost: x\r\ncontent-LENGTH:  5 \r\nConnection: close\r\n\r\n");
    try testing.expectEqualStrings("PUT", head.method);
    try testing.expectEqualStrings("/kv/a", head.target);
    try testing.expectEqual(Version.@"HTTP/1.1", head.version);
    try testing.expectEqual(5, head.content_length);
    try testing.expect(!head.chunked);

    const chunked = try parseHead("POST / HTTP/1.1\nTransfer-Encoding: gzip, Chunked\n\n");
    try testing.expect(chunked.chunked);
    try testing.expect(chunked.hasBody());

    try testing.expectError(error.BadRequest, parseHead("GET /\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseHead("GET / HTTP/2.0\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseHead("GET / HTTP/1.1\r\nContent-Length: -1\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseHead("GET / HTTP/1.1\r\nContent-Length: 1\r\nContent-Length: 2\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseHead("GET / HTTP/1.1\r\nContent-Length: 1\r\nTransfer-Encoding: chunked\r\n\r\n"));
    try testing.expectError(error.ExpectationFailed, parseHead("GET / HTTP/1.1\r\nExpect: nope\r\n\r\n"));
}

test readHead {
    var in: Io.Reader = .fixed("GET /health HTTP/1.1\r\n\r\nrest" ++ ("x" ** max_head_len));
    const head = try readHead(&in);
    try testing.expectEqualStrings("/health", head.target);
    try testing.expectEqualStrings("rest", in.buffered()[0..4]);

    var oversized: Io.Reader = .fixed("GET / HTTP/1.1\r\nX: " ++ ("x" ** max_head_len) ++ "\r\n\r\n");
    try testing.expectError(error.HeadTooLarge, readHead(&oversized));
}

test "chunked body" {
    const head: Head = .{ .method = "PUT", .target = "/", .version = .@"HTTP/1.1", .chunked = true };

    var in: Io.Reader = .fixed("5;ext=1\r\nhello\r\n6\r\n world\r\n0\r\nTrailer: x\r\n\r\nnext");
    const body = try readBody(&in, testing.allocator, head, 64);
    defer testing.allocator.free(body);
    try testing.expectEqualStrings("hello world", body);
    try testing.expectEqualStrings("next", in.buffered());

    var too_large: Io.Reader = .fixed("5\r\nhello\r\n0\r\n\r\n");
    try testing.expectError(error.TooLarge, readBody(&too_large, testing.allocator, head, 4));

    var malformed: Io.Reader = .fixed("zz\r\n");
    try testing.expectError(error.BadRequest, discardBody(&malformed, head, 64));
}

test "content-length body" {
    const head: Head = .{ .method = "PUT", .target = "/", .version = .@"HTTP/1.1", .content_length = 3 };
    var in: Io.Reader = .fixed("abcdef");
    const body = try readBody(&in, testing.allocator, head, 3);
    defer testing.allocator.free(body);
    try testing.expectEqualStrings("abc", body);
    try testing.expectError(error.TooLarge, readBody(&in, testing.allocator, head, 2));
    try discardBody(&in, head, 3);
    try testing.expectEqual(0, in.buffered().len);
}

test writeResponse {
    var buf: [256]u8 = undefined;
    var out: Io.Writer = .fixed(&buf);
    try writeResponse(&out, .{ .status = .method_not_allowed, .body = "nope", .allow = "GET" });
    try testing.expectEqualStrings(
        "HTTP/1.1 405 Method Not Allowed\r\nAllow: GET\r\nContent-Length: 4\r\n" ++
            "Content-Type: text/plain; charset=utf-8\r\nConnection: close\r\n\r\nnope",
        out.buffered(),
    );
}

//! kvhttp: an in-memory HTTP/1.1 key-value server.
//!
//! Usage: app <port>

const std = @import("std");
const net = std.Io.net;

const Server = @import("Server.zig");
const Store = @import("Store.zig");

pub const std_options: std.Options = .{
    .log_level = .info,
};

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const gpa = init.gpa;

    const args = try init.minimal.args.toSlice(init.arena.allocator());
    const port = parsePort(args) orelse {
        std.log.err("usage: app <port>", .{});
        std.process.exit(2);
    };

    var store: Store = .init(gpa);
    defer store.deinit();

    const address: net.IpAddress = .{ .ip4 = .loopback(port) };
    var listener = address.listen(io, .{ .kernel_backlog = 511, .reuse_address = true }) catch |err| {
        std.log.err("cannot listen on 127.0.0.1:{d}: {t}", .{ port, err });
        std.process.exit(1);
    };
    defer listener.deinit(io);

    std.log.info("kvhttp listening on http://127.0.0.1:{d}", .{port});

    var server: Server = .{ .io = io, .gpa = gpa, .store = &store };
    try server.run(&listener);
}

fn parsePort(args: []const [:0]const u8) ?u16 {
    if (args.len != 2) return null;
    const port = std.fmt.parseInt(u16, args[1], 10) catch return null;
    return if (port == 0) null else port;
}

test parsePort {
    try std.testing.expectEqual(8080, parsePort(&.{ "app", "8080" }));
    try std.testing.expectEqual(null, parsePort(&.{"app"}));
    try std.testing.expectEqual(null, parsePort(&.{ "app", "0" }));
    try std.testing.expectEqual(null, parsePort(&.{ "app", "65536" }));
    try std.testing.expectEqual(null, parsePort(&.{ "app", "http" }));
}

test {
    _ = @import("http.zig");
    _ = Server;
    _ = Store;
}
